def minMaxGame(nums):
    n = len(nums)
    # Repeat until only one element is left
    while n > 1:
        for i in range(n // 2):
            # Even index: take min, odd index: take max
            if i % 2 == 0:
                nums[i] = min(nums[2 * i], nums[2 * i + 1])
            else:
                nums[i] = max(nums[2 * i], nums[2 * i + 1])
        n //= 2  # Each round halves the array size
    return nums[0]
